import{_ as p,a0 as r,w as l,s as m,ao as a,I as i,x as o,a1 as n,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"Gentoo Linux 現在提供用於快速軟件安裝的二進制包 | LCTT x X-CMD","titleTemplate":false,"description":"Gentoo Linux 現在提供用於快速軟件安裝的二進制包 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Gentoo Linux 現在提供用於快速軟件安裝的二進制包 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Gentoo Linux 現在提供用於快速軟件安裝的二進制包 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20231230 Big News- Gentoo Linux is Now Providing Binary Packages for Quick Software Installation","title":"Gentoo Linux 現在提供用於快速軟件安裝的二進制包","tag":"202401","desc":""},"relativePath":"202401/20231230 Big News- Gentoo Linux is Now Providing Binary Packages for Quick Software Installation.md","filePath":"[post].md"}'),g={name:"202401/20231230 Big News- Gentoo Linux is Now Providing Binary Packages for Quick Software Installation.md"};function u(d,t,f,x,w,G){const e=r("Link");return l(),m("div",null,[t[21]||(t[21]=a('<h1 id="gentoo-linux-現在提供用於快速軟件安裝的二進制包" tabindex="-1">Gentoo Linux 現在提供用於快速軟件安裝的二進制包 <a class="header-anchor" href="#gentoo-linux-現在提供用於快速軟件安裝的二進制包" aria-label="Permalink to “Gentoo Linux 現在提供用於快速軟件安裝的二進制包”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202401/03/142406n5k61kq3xddmu8mk.jpg" alt=""></p><blockquote><p>Gentoo 為硬件速度慢的用户準備了一份年終大禮。</p></blockquote><p>如果你不覺得這有什麼大不了，那就説明你不瞭解 Gentoo。</p><p>Debian 有 deb 軟件包，Fedora 有 RPM 軟件包。甚至 Arch Linux 也提供了通過 Pacman 命令安裝的二進制包。基本上，這些發行版從源代碼構建這些包並將其提供給你。你可以使用發行版的包管理系統來獲取這些二進制文件並將它們安裝在你的系統上。</p><p>但進入 Gentoo 領域，情況就完全不同了。想要安裝任何軟件嗎？ 你必須從源代碼編譯它。</p><p>是的，你沒看錯。這就是圍繞編譯和 Gentoo 產生了如此多的表情包的原因。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-ifi-it-moves-compile-it.png" alt="A blend of Gentoo and dad joke"></p><p>從源代碼編譯軟件的問題意味着它將需要更多的計算能力。當你編譯軟件時，你的 CPU 將非常繁忙。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-compile-meme.png" alt=""></p><p>當然，編譯一個軟件需要一些時間。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-compile-time-meme.webp" alt="Image source: r/linuxmemes"></p><h3 id="現在你可以在-gentoo-中-安裝-軟件包而不是編譯它們" tabindex="-1">現在你可以在 Gentoo 中“安裝”軟件包而不是編譯它們 <a class="header-anchor" href="#現在你可以在-gentoo-中-安裝-軟件包而不是編譯它們" aria-label="Permalink to “現在你可以在 Gentoo 中“安裝”軟件包而不是編譯它們”">​</a></h3><p>Gentoo 的包管理器 Portage 多年來一直支持二進制包。只是沒有預編譯二進制包的集中倉庫。</p><p>現在這種情況正在改變，因為 Gentoo 現在提供二進制包供下載和直接安裝。</p>',15)),i("p",null,[t[1]||(t[1]=o("對於大多數架構，它將僅限於核心系統和每週更新。然而，對於 ",-1)),n(e,{href:"https://itsfoss.com/arm-aarch64-x86_64/"},{default:s(()=>[...t[0]||(t[0]=[o("amd64 和 arm64",-1)])]),_:1}),t[2]||(t[2]=o("，有一個為 LibreOffice、Docker、Plasma、GNOME 等流行軟件提供二進制文件的巨大倉庫。",-1))]),t[22]||(t[22]=i("p",null,"這對於使用低端硬件或不希望一直手動編譯的 Gentoo 用户來説非常方便。",-1)),i("p",null,[t[4]||(t[4]=o("我知道你對在 Gentoo 中使用二進制包有很多疑問。查看 ",-1)),n(e,{href:"https://www.gentoo.org/news/2023/12/29/Gentoo-binary.html"},{default:s(()=>[...t[3]||(t[3]=[o("Gentoo 的官方公告",-1)])]),_:1}),t[5]||(t[5]=o("，其中包含詳細內容。",-1))]),t[23]||(t[23]=a('<p><img src="https://www.gentoo.org/assets/img/logo/icon-192.png" alt=""></p><h3 id="基於源代碼的安裝不會消失" tabindex="-1">基於源代碼的安裝不會消失 <a class="header-anchor" href="#基於源代碼的安裝不會消失" aria-label="Permalink to “基於源代碼的安裝不會消失”">​</a></h3><p>先別生氣，我的 Gentoo 夥計！你仍然可以享受從源代碼編譯的樂趣。這個選項不會消失。你仍然可以像以前一樣享受編譯的樂趣。二進制軟件包是可選的。它們不會強迫你使用。</p><p>編譯每一個包有其好處。軟件針對其運行的系統進行了優化。這就是 Gentoo 用户所誇耀的性能提升。</p><p><img src="https://news.itsfoss.com/content/images/2023/12/gentoo-faster-meme.png" alt=""></p><p>由於系統資源有限，低端計算機需要更長的編譯時間，但它也可以通過為機器構建每個軟件來獲得性能優化。如果你問我的話，這有點像第 22 條軍規的情況。</p><h3 id="你用-gentoo-嗎" tabindex="-1">你用 Gentoo 嗎？ <a class="header-anchor" href="#你用-gentoo-嗎" aria-label="Permalink to “你用 Gentoo 嗎？”">​</a></h3><p>我堅信這不僅會為現有的 Gentoo 用户羣帶來便利，而且還將有助於擴大其用户羣。畢竟，一個發行版用户在安裝 Arch 之後會做什麼呢？</p><p>我在這裏的新聞報道中使用了很多表情包，因為現在是快樂的季節 ☃️</p><p>也許你可以利用寒假安裝（但不編譯）Gentoo 😜</p><p>享受節日和假期！</p><p><em>（題圖：DA/389d8213-29fd-4149-b591-45e6cc9b0bb0）</em></p><hr>',13)),i("p",null,[t[7]||(t[7]=o("via: ",-1)),n(e,{href:"https://news.itsfoss.com/gentoo-binary-packages/"},{default:s(()=>[...t[6]||(t[6]=[o("https://news.itsfoss.com/gentoo-binary-packages/",-1)])]),_:1})]),i("p",null,[t[12]||(t[12]=o("作者：",-1)),n(e,{href:"https://news.itsfoss.com/author/root/"},{default:s(()=>[...t[8]||(t[8]=[o("Abhishek",-1)])]),_:1}),t[13]||(t[13]=o(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[9]||(t[9]=[o("lujun9972",-1)])]),_:1}),t[14]||(t[14]=o(" 譯者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:s(()=>[...t[10]||(t[10]=[o("geekpi",-1)])]),_:1}),t[15]||(t[15]=o(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[11]||(t[11]=[o("wxy",-1)])]),_:1})]),i("p",null,[t[18]||(t[18]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[16]||(t[16]=[o("LCTT",-1)])]),_:1}),t[19]||(t[19]=o(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:s(()=>[...t[17]||(t[17]=[o("Linux中國",-1)])]),_:1}),t[20]||(t[20]=o(" 榮譽推出",-1))])])}const P=p(g,[["render",u]]);export{k as __pageData,P as default};
